+                    new TransportRequest.Empty(),
+                    new ActionListenerResponseHandler<TransportResponse>(
+                        l,
+                        in -> TransportResponse.Empty.INSTANCE,
+                        EsExecutors.DIRECT_EXECUTOR_SERVICE
+                    )
+                )
+            )
+        );
+    }
