+            properties:
+              name:
+                type: keyword
+              vector:
+                type: dense_vector
+                dims: 4
+                index: true
+                similarity: l2_norm
+                index_options:
+                  type: int4_hnsw
+              another_vector:
+                type: dense_vector
+                dims: 4
+                index: true
+                similarity: l2_norm
+                index_options:
+                  type: int4_hnsw
+
+  - do:
+      index:
+        index: hnsw_byte_quantized
+        id: "1"
+        body:
+          name: cow.jpg
+          vector: [230.0, 300.33, -34.8988, 15.555]
+          another_vector: [130.0, 115.0, -1.02, 15.555]
+
+  # Flush in order to provoke a merge later
+  - do:
+      indices.flush: { }
+
+  - do:
+      index:
+        index: hnsw_byte_quantized
+        id: "2"
+        body:
+          name: moose.jpg
+          vector: [-0.5, 100.0, -13, 14.8]
+          another_vector: [-0.5, 50.0, -1, 1]
+
+  # Flush in order to provoke a merge later
+  - do:
+      indices.flush: { }
+
+  - do:
+      index:
+        index: hnsw_byte_quantized
+        id: "3"
+        body:
+          name: rabbit.jpg
+          vector: [0.5, 111.3, -13.0, 14.8]
+          another_vector: [-0.5, 11.0, 0, 12]
+
+  - do:
+      indices.forcemerge:
+        index: hnsw_byte_quantized
+        max_num_segments: 1
+
+  - do:
+      indices.refresh: {}
+
+---
+"kNN search only":
+  - do:
+      search:
+        index: hnsw_byte_quantized
+        body:
+          fields: [ "name" ]
+          knn:
+            field: vector
+            query_vector: [-0.5, 90.0, -10, 14.8]
+            k: 2
+            num_candidates: 3
+
+  - match: {hits.hits.0._id: "2"}
+  - match: {hits.hits.0.fields.name.0: "moose.jpg"}
+
+  - match: {hits.hits.1._id: "3"}
+  - match: {hits.hits.1.fields.name.0: "rabbit.jpg"}
+---
+"kNN multi-field search only":
+  - do:
+      search:
+        index: hnsw_byte_quantized
+        body:
+          fields: [ "name" ]
+          knn:
+           - {field: vector, query_vector: [-0.5, 90.0, -10, 14.8], k: 2, num_candidates: 3}
