-     *       "text": {
-     *           "type": "text",
-     *           "searchable": false,
-     *           "aggregatable": false,
-     *           "indices": [
-     *               "bar",
-     *               "foo"
-     *           ],
-     *           "non_searchable_indices": [
-     *               "foo"
-     *           ]
-     *       },
-     *       "keyword": {
-     *           "type": "keyword",
-     *           "searchable": false,
-     *           "aggregatable": true,
-     *           "non_aggregatable_indices": [
-     *               "bar", "baz"
-     *           ]
-     *       }
-     *   }
